//! Phase-0 oracle: Python and Rust `ensure_job_id` digests must agree exactly.
//!
//! The fixture is generated by `src/lake/tests/oracle/generate.py`.

use lake_contracts::{AssetClass, DataType, Date};
use lake_coverage::{ensure_job_id, EnsureSpec};
use serde_json::Value;

fn oracle() -> Vec<Value> {
    serde_json::from_str(include_str!("oracle/ensure_job_ids.json")).expect("ensure oracle")
}

#[test]
fn oracle_ensure_job_ids_match() {
    let entries = oracle();
    assert!(!entries.is_empty());
    for entry in &entries {
        let asset_class = AssetClass::from_value(entry["asset_class"].as_str().expect("asset"))
            .expect("known asset class");
        let data_type = DataType::from_value(entry["data_type"].as_str().expect("type"))
            .expect("known data type");
        let spec = EnsureSpec {
            asset_class,
            data_type,
            symbol: entry["symbol"].as_str().expect("symbol").to_string(),
            start_date: Date::parse(entry["start_date"].as_str().expect("start")).expect("start"),
            end_date: Date::parse(entry["end_date"].as_str().expect("end")).expect("end"),
        };
        let job_id = ensure_job_id(&spec).expect("job id");
        assert_eq!(
            job_id,
            entry["job_id"].as_str().expect("oracle job id"),
            "job id mismatch for {asset_class}/{data_type}/{}",
            spec.symbol
        );
    }
}
